#include <bits/stdc++.h>
using namespace std;

#define int long long

void solve(){
    int n;cin>>n;
    int m = 3*n;
    vector<int> vec(3*n+1);
    for(int i=1;i<=3*n;i++) cin>>vec[i];
    sort(vec.begin(), vec.end());
    vector<int> pref(m+1, 0);
    for(int i=1;i<=m;i++){
        pref[i] = pref[i-1] + vec[i];
    }
    int mx = 0;
    for(int x=0;x<=n;x++){
        int ans = (pref[m] - pref[m-x])*6;
        int l = 2*x+1, r = m-x;
        int ct = r-l+1;
        if(ct<3){
            mx = max(mx, ans);
            continue;
        }
        int lo=l, hi = l+(ct/3)-1;
        
        // sirf 4 wale
        int p = l + (ct/3) - 1;
        if(3*vec[p] < vec[p+1]+vec[p+2]){
            int val = ans + (pref[r] - pref[p])*4;
            mx = max(mx, val);
            continue;
        }
        
        while(hi-lo > 1){
            int mid = (lo+hi)/2;
            int curr = mid-l+1;
            int i= r - 2*curr+1;
            if(3*vec[mid]>vec[i]+vec[i+1]){
                hi = mid;
            }else{
                lo = mid+1;
            }
        }
        // lo ke liye
        int curr = lo-l+1;
        int i = r - 2*curr+1;
        if(3*vec[lo] > vec[i] + vec[i+1]){
            hi = lo;
        }
        int count4 = hi - l;
        ans += 4*(pref[r] - pref[r - 2*count4]);
        ans += 3*(pref[r-2*count4] - pref[hi-1]);
        mx = max(mx, ans);
    }
    cout<<mx<<endl;
}

signed main() {
	int t; cin >> t;
	while(t--) solve();
}
